<?php require dirname(__DIR__).'/app/bootstrap.php'; require dirname(__DIR__).'/app/layout.php';
$products=db()->query('SELECT * FROM products ORDER BY productId DESC')->fetchAll();$photosByProduct=photosForProducts($products);pageStart('Products'); ?><h1>Products</h1><div class="grid">
<?php foreach($products as $p): ?><article class="card"><?php $gallery=array_values(array_filter(galleryForProduct($p,$photosByProduct),static fn($photo)=>$photo['url']!==null));if(!$gallery && ($fallback=photoUrl($p['photo_key'])))$gallery=[['url'=>$fallback]]; ?>
<?php if($gallery): ?><div class="product-gallery"><img class="gallery-main" src="<?= e($gallery[0]['url']) ?>" alt="<?= e($p['name']) ?>" loading="lazy"><div class="gallery-thumbs"><?php foreach($gallery as $i=>$photo): ?><button type="button" class="gallery-thumb <?= $i===0?'selected':'' ?>" aria-label="View photo <?= $i+1 ?> of <?= e($p['name']) ?>" aria-pressed="<?= $i===0?'true':'false' ?>" data-url="<?= e($photo['url']) ?>"><img src="<?= e($photo['url']) ?>" alt="" loading="lazy"></button><?php endforeach; ?></div></div><?php endif; ?>
<h2><?= e($p['name']) ?></h2><p><?= nl2br(e($p['description'])) ?></p><strong>$<?= number_format((float)$p['price'],2) ?></strong></article><?php endforeach; ?></div><?php if(!$products): ?><p>No products yet.</p><?php endif; ?>
<script>document.querySelectorAll('.gallery-thumb').forEach(button=>button.addEventListener('click',()=>{const gallery=button.closest('.product-gallery');gallery.querySelector('.gallery-main').src=button.dataset.url;gallery.querySelectorAll('.gallery-thumb').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button));});}));</script>
<?php pageEnd();
